const helpThreads=new Map(),helpGuides=new Map();
globalThis.fetch=async(url,init={})=>{
 const path=String(url).replace('https://discord.com/api/v10',''),method=init.method||'GET';discordCalls.push({path,method,body:init.body?JSON.parse(init.body):null});
 const response=value=>new Response(JSON.stringify(value),{status:200,headers:{'content-type':'application/json'}});
 if(method==='GET'&&path==='/guilds/guild/channels')return response(channelCreated?[{id:'help-channel',type:0,name:'ufb-help',topic:'UFB_HELP_CENTER_V1'}]:[]);
 if(method==='POST'&&path==='/guilds/guild/channels'){channelCreated=true;return response({id:'help-channel',type:0,name:'ufb-help',topic:'UFB_HELP_CENTER_V1'});}
 if(method==='GET'&&path==='/guilds/guild/threads/active')return response({threads:[...helpThreads.values()],has_more:false});
 if(method==='GET'&&path==='/channels/help-channel/threads/archived/public?limit=100')return response({threads:[],has_more:false});
 if(method==='GET'&&path==='/channels/help-channel')return response({id:'help-channel',type:0,name:'ufb-help',topic:'UFB_HELP_CENTER_V1'});
 if(method==='GET'&&path==='/channels/help-channel/messages?limit=100')return response(indexMessage?[indexMessage]:[]);
 if(method==='POST'&&path==='/channels/help-channel/messages'){const created={id:`message-${++messageNumber}`,embeds:JSON.parse(init.body).embeds};if(created.embeds)indexMessage=created;return response(created);}
 if(method==='POST'&&path.endsWith('/threads')){const thread={id:`thread-${++threadNumber}`,type:11,parent_id:'help-channel',owner_id:'bot-app',name:JSON.parse(init.body).name};helpThreads.set(thread.id,thread);return response(thread);}
 if(method==='GET'&&/^\/channels\/thread-\d+\/messages\?limit=100$/.test(path))return response(helpGuides.has(path.split('/')[2])?[helpGuides.get(path.split('/')[2])]:[]);
 if(method==='POST'&&/^\/channels\/thread-\d+\/messages$/.test(path)){const guide={id:`guide-${++messageNumber}`,embeds:JSON.parse(init.body).embeds};helpGuides.set(path.split('/')[2],guide);return response(guide);}
 if(method==='PATCH'&&/^\/channels\/thread-\d+\/messages\//.test(path)&&!helpGuides.has(path.split('/')[2]))return new Response('not found',{status:404});
 if(method==='PATCH')return response({id:path.split('/').pop()});
 return new Response('not found',{status:404});
};
try{
 const help=interaction('administrator','setup','helpcenter');help.member.permissions='8';help.application_id='bot-app';
 const helpEnv={...env,DISCORD_BOT_TOKEN:'test-token',DISCORD_APPLICATION_ID:'bot-app'};
 assert.match((await handleCommand(helpEnv,help)).data.content,/5 category threads/);
 assert.equal(discordCalls.filter(call=>call.method==='POST'&&call.path==='/guilds/guild/channels').length,1);
 assert.equal(discordCalls.filter(call=>call.method==='POST'&&call.path.endsWith('/threads')).length,5);
 assert.equal(db.prepare("SELECT channel_id FROM help_centers WHERE guild_id='guild'").get().channel_id,'help-channel');
 await handleCommand(helpEnv,help);
 assert.equal(discordCalls.filter(call=>call.method==='POST'&&call.path==='/guilds/guild/channels').length,1);
 assert.equal(discordCalls.filter(call=>call.method==='POST'&&call.path.endsWith('/threads')).length,5);
 assert.ok(discordCalls.filter(call=>call.method==='PATCH'&&/^\/channels\/thread-\d+$/.test(call.path)).length>=5);
 const firstThread=db.prepare("SELECT state_json FROM help_centers WHERE guild_id='guild'").get().state_json;
 const firstStart=JSON.parse(firstThread).sections.start;
 helpGuides.delete(firstStart.threadId);
 await handleCommand(helpEnv,help);
 assert.equal(discordCalls.filter(call=>call.method==='POST'&&call.path.endsWith('/threads')).length,5,'missing guide must not create a new thread');
 assert.notEqual(JSON.parse(db.prepare("SELECT state_json FROM help_centers WHERE guild_id='guild'").get().state_json).sections.start.messageId,firstStart.messageId);
 db.prepare("DELETE FROM help_centers WHERE guild_id='guild'").run();
 await handleCommand(helpEnv,help);
 assert.equal(discordCalls.filter(call=>call.method==='POST'&&call.path.endsWith('/threads')).length,5,'lost state must adopt existing threads');
 assert.equal(discordCalls.filter(call=>call.method==='POST'&&call.path==='/channels/help-channel/messages'&&call.body?.embeds).length,1,'lost state must adopt the existing index');
 helpThreads.set('thread-6',{id:'thread-6',type:11,parent_id:'help-channel',owner_id:'bot-app',name:'1 · Start Here'});
 helpGuides.set('thread-6',{id:'old-copy-guide',embeds:[{title:'1 · Start Here'}]});
 await handleCommand(helpEnv,help);
 assert.ok(discordCalls.some(call=>call.path==='/channels/thread-6'&&call.method==='PATCH'&&call.body?.archived===true),'old duplicate thread should be archived');
 assert.equal(discordCalls.filter(call=>call.method==='POST'&&call.path.endsWith('/threads')).length,5);
 db.prepare("INSERT INTO bot_metadata(key,value) VALUES('help_center_lock:guild','other-refresh')").run();
 const beforeLocked=discordCalls.length;
 assert.match((await handleCommand(helpEnv,help)).data.content,/already running/);
 assert.equal(discordCalls.length,beforeLocked,'concurrent refresh must not publish');
 db.prepare("DELETE FROM bot_metadata WHERE key='help_center_lock:guild'").run();
 await refreshExistingHelpCenters(helpEnv);
 const rsvpGuide=discordCalls.find(call=>call.method==='PATCH'&&call.body?.embeds?.[0]?.description?.includes('name:Practice Nights'));
 assert.ok(rsvpGuide);assert.match(rsvpGuide.body.embeds[0].description,/reminders go inside the event thread/);
 assert.equal(db.prepare("SELECT value FROM bot_metadata WHERE key='help_center_content:guild'").get().value,'20260929-team-managers-v2');
 const callsAfterRefresh=discordCalls.length;await refreshExistingHelpCenters(helpEnv);assert.equal(discordCalls.length,callsAfterRefresh);
 assert.equal(discordCalls.filter(call=>call.method==='POST'&&call.path.endsWith('/threads')).length,5);
}finally{globalThis.fetch=originalFetch;}
console.log('PASS: /setup helpcenter creates one read-only documentation channel, five live category threads and refreshes them without duplicates.');

// Official EA Tracker cards are the patch-note source; every server opts in independently.
const patchCard={id:'6abab3d79708ac341a108a7c',name:'FC 27 v1.0.2 - Small Bug Fix Update',desc:'EA SPORTS FC 27 version 1.0.2 is coming soon.\n\n**Ultimate Team**\n- Some countries were not available in the FC Pro Open Registration List.',shortUrl:'https://trello.com/c/L45frZPE'};
assert.equal(parseEaPatchCards([
 patchCard,
 {...patchCard,id:'6ab2bed10dd27f06b4b6a30b',name:'FC 26 v1.0.2'},
 {...patchCard,id:'6ab2bed10dd27f06b4b6a31b',name:'FC 27 Community Update'},
 {...patchCard,id:'6ab2bed10dd27f06b4b6a32b',name:'FC 27 FUT Spotlight v1.0.2'},
 {...patchCard,id:'6ab2bed10dd27f06b4b6a33b',name:'FC 27 Launch Developer Update'}
]).length,1,'Only patch notes and fixes should pass the EA Tracker filter');
assert.equal(parseEaPatchCards([
 {...patchCard,id:'6ab2bed10dd27f06b4b6a34b',name:'FC 27 Hotfix'},
 {...patchCard,id:'6ab2bed10dd27f06b4b6a35b',name:'FC 27 Title Update #2'},
 {...patchCard,id:'6ab2bed10dd27f06b4b6a36b',name:'FC 27 Update Notes'}
]).length,3);
const patchCalls=[];let currentPatch={...patchCard},steamPatchNews=[];
globalThis.fetch=async(url,init={})=>{
 const target=String(url),method=init.method||'GET';patchCalls.push({target,method,body:init.body?JSON.parse(init.body):null});
 if(target.includes('api.trello.com/1/boards/'))return Response.json([currentPatch]);
 if(target.includes('api.steampowered.com/'))return Response.json({appnews:{newsitems:steamPatchNews}});
 const guildMatch=/\/guilds\/(patch-guild|other-guild)\/channels$/.exec(target);
 if(guildMatch&&method==='GET')return Response.json([]);
 if(guildMatch&&method==='POST')return Response.json({id:`${guildMatch[1]}-patch-channel`,type:0});
 const channelMatch=/\/channels\/((?:patch-guild|other-guild)-patch-channel)$/.exec(target);
 if(channelMatch&&method==='GET')return Response.json({id:channelMatch[1],type:0});
 const messageMatch=/\/channels\/((?:patch-guild|other-guild)-patch-channel)\/messages$/.exec(target);
 if(messageMatch&&method==='POST')return Response.json({id:`${messageMatch[1]}-message`});
 if(/\/channels\/((?:patch-guild|other-guild)-patch-channel)\/messages\/\1-message$/.test(target)&&method==='PATCH')return Response.json({id:'updated-message'});
 return new Response('not found',{status:404});
};
