 const patchEnv={...env,DISCORD_BOT_TOKEN:'test-token'};
 const setupPatch={...interaction('administrator','setup','patches'),guild_id:'patch-guild',application_id:'test-app',member:{user:{id:'administrator',username:'administrator'},roles:[],permissions:'8'}};
