 assert.equal(patchCalls.filter(call=>call.method==='POST'&&call.target.endsWith('/guilds/patch-guild/channels')).length,1);
 assert.equal(patchCalls.filter(call=>call.method==='POST'&&call.target.endsWith('/channels/patch-guild-patch-channel/messages')).length,1);
 assert.equal(patchCalls.filter(call=>call.method==='POST'&&call.target.endsWith('/channels/other-guild-patch-channel/messages')).length,1);
 assert.match(patchCalls.find(call=>call.method==='POST'&&call.target.endsWith('/channels/patch-guild-patch-channel/messages')).body.embeds[0].description,/Announced/);
 await handleCommand(patchEnv,setupPatch);
 assert.equal(patchCalls.filter(call=>call.method==='POST'&&call.target.endsWith('/channels/patch-guild-patch-channel/messages')).length,1,'Rerunning setup must not duplicate a patch post');
 steamPatchNews=[{title:'EA SPORTS FC 27 Version 1.0.2',contents:'EA SPORTS FC 27 version 1.0.2 is now live.'}];
 const sourceCallsBeforePoll=patchCalls.filter(call=>call.target.includes('api.trello.com/')).length;
 await pollPatchUpdates(patchEnv,Date.now()+16*60_000);
 assert.equal(patchCalls.filter(call=>call.target.includes('api.trello.com/')).length,sourceCallsBeforePoll+1,'One feed fetch should serve all due guilds');
