assert.equal(db.prepare("SELECT COUNT(*) AS n FROM leagues WHERE guild_id='other-guild'").get().n,3,'another guild league was deleted');
assert.equal(db.prepare("SELECT COUNT(*) AS n FROM teams t JOIN leagues l ON l.id=t.league_id WHERE l.guild_id='other-guild'").get().n,1,'another guild team was deleted');
assert.equal(db.prepare("SELECT COUNT(*) AS n FROM guild_player_claims WHERE guild_id='other-guild'").get().n,1,'another guild claim was deleted');
