const ownerTeamAutocomplete=fresh('bot-owner','linkclub',null);ownerTeamAutocomplete.member.roles=[];ownerTeamAutocomplete.member.permissions='0';ownerTeamAutocomplete.type=4;ownerTeamAutocomplete.data={name:'linkclub',options:[{name:'team',value:'Fresh',focused:true}]};assert.ok((await handleCommand(ownerEnv,ownerTeamAutocomplete)).data.choices.some(choice=>choice.value===String(freshTeam)));
const ownerDissolve=fresh('bot-owner','team','dissolve',{team:String(freshTeam)});ownerDissolve.member.roles=[];ownerDissolve.member.permissions='0';assert.match((await handleCommand(ownerEnv,ownerDissolve)).data.content,/Nothing changed.*confirm:true/);
const outsiderDissolve=fresh('outsider','team','dissolve',{team:String(freshTeam)});outsiderDissolve.member.roles=[];outsiderDissolve.member.permissions='0';assert.match((await handleCommand(env,outsiderDissolve)).data.content,/Only that team’s manager/);
const ownerLink=fresh('bot-owner','linkclub',null);ownerLink.member.roles=[];ownerLink.member.permissions='0';ownerLink.data={name:'linkclub',options:[{name:'league',value:'fresh-6v6'},{name:'team',value:String(freshTeam)},{name:'club',value:'Fresh FC'},{name:'platform',value:'common-gen5'}]};assert.match((await handleCommand(ownerEnv,ownerLink,freshEa)).data.embeds[0].title,/linked/);
const freshLink=fresh('fresh-manager','linkclub',null);freshLink.member.roles=['fresh-managers'];freshLink.data={name:'linkclub',options:[{name:'league',value:'fresh-6v6'},{name:'team',value:String(freshTeam)},{name:'club',value:'Fresh FC'},{name:'platform',value:'common-gen5'}]};
assert.match((await handleCommand(env,freshLink,freshEa)).data.embeds[0].title,/linked/);
const freshMatches=fresh('fresh-manager','matches',null);freshMatches.data={name:'matches',options:[{name:'league',value:'fresh-6v6'},{name:'team',value:String(freshTeam)}]};
assert.match((await handleCommand(env,freshMatches,freshEa)).data.embeds[0].title,/Recent matches/);
const freshAuto=fresh('fresh-manager','automode','start',{team:String(freshTeam)});freshAuto.member.roles=['fresh-managers'];
assert.match((await handleCommand(env,freshAuto)).data.content,/Monitoring started/);
freshAuto.data.options[0].name='stop';assert.match((await handleCommand(env,freshAuto)).data.content,/stopped/);
